const select=(e,t=!1)=>(e=e.trim(),t?[...document.querySelectorAll(e)]:document.querySelector(e)),onscroll=(e,t)=>{e.addEventListener("scroll",t)};let navbarlinks=select("#navbar .scrollto",!0);const navbarlinksActive=()=>{let e=window.scrollY+200;navbarlinks.forEach(t=>{if(!t.hash)return;let l=select(t.hash);l&&(e>=l.offsetTop&&e<=l.offsetTop+l.offsetHeight?t.classList.add("active"):t.classList.remove("active"))})};window.addEventListener("load",navbarlinksActive),onscroll(document,navbarlinksActive);